<script lang="ts">
 import { page } from '$app/state';import { goto } from '$app/navigation';import { onDestroy } from 'svelte';
 let {model,t,lang='de'}:{lang?:string;model:Record<string,any[]>;t:(key:string)=>string}=$props();let search=$state(''),scanning=$state(false),video=$state<HTMLVideoElement>(),stream:MediaStream|undefined,interval:ReturnType<typeof setInterval>|undefined,message=$state('');
 let visible=$derived(model.vessels.filter(v=>v.name.toLowerCase().includes(search.toLowerCase())||v.code.toLowerCase().includes(search.toLowerCase())).filter(v=>!page.url.searchParams.get('vessel')||v.id===page.url.searchParams.get('vessel')));
 function stop(){scanning=false;stream?.getTracks().forEach(track=>track.stop());if(interval)clearInterval(interval);}
 onDestroy(stop);
 async function scan(){const Detector=(window as any).BarcodeDetector;if(!Detector){message=t('manualSearch');return;}scanning=true;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const camera=video;if(!camera){stop();return;}camera.srcObject=stream;await camera.play();const detector=new Detector({formats:['qr_code']});interval=setInterval(async()=>{const codes=await detector.detect(camera);if(codes[0]){try{const url=new URL(codes[0].rawValue);if(url.origin===location.origin&&url.pathname==='/app/cellar'){stop();await goto(url.pathname+url.search);}}catch{message=t('manualSearch');}}},500);}catch{message=t('manualSearch');stop();}}
</script>
<section class="card"><h2>{t('vessel_id')}</h2><div class="search"><label>{t('search')}<input bind:value={search} placeholder={t('code')} /></label><button onclick={()=>scanning?stop():scan()}>{scanning?t('done'):t('scanQr')}</button>{#if page.url.searchParams.has('vessel')}<a href="/app/cellar">{t('all')}</a>{/if}</div>{#if scanning}<video bind:this={video} autoplay muted playsinline><track kind="captions" /></video>{/if}<p role="status">{message}</p><div class="tanks">{#each visible as vessel}{@const positions=model.positions.filter(p=>p.vessel_id===vessel.id&&Number(p.quantity_l)>0)}{@const volume=positions.reduce((sum,p)=>sum+Number(p.quantity_l),0)}<article><a href={'/app/cellar?vessel='+vessel.id}><strong>{vessel.code}</strong><span>{vessel.name}</span></a><meter min="0" max={Number(vessel.capacity_l)} value={volume}>{volume} L</meter><p>{volume.toLocaleString(lang)} / {Number(vessel.capacity_l).toLocaleString(lang)} L · {t(vessel.status)}</p>{#each positions as position}<small>{position.lot_code} · {position.lot_name}</small>{/each}<details><summary>QR</summary><a href={'/api/qr/'+vessel.id} download={'vinea-'+vessel.code+'.png'}><img src={'/api/qr/'+vessel.id} alt={'QR '+vessel.code} width="130" height="130" loading="lazy" /></a></details></article>{/each}</div></section>
<style>.search{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.tanks{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-top:16px}.tanks article{background:#f7f9f3;padding:16px;border:1px solid #e1e7da;border-radius:9px}.tanks a{display:grid;gap:5px;text-decoration:none}.tanks span,.tanks p,.tanks small{font-size:11px;color:#6e7f66}.tanks strong{font:24px Georgia}meter{width:100%;margin:18px 0 0;height:15px}small{display:block}details{margin-top:15px}summary{font-size:10px;cursor:pointer}video{max-width:350px;width:100%;margin-top:20px}</style>
